<?php $streamcreedRows = is_array($rRows ?? null) ? $rRows : []; $streamcreedPeriod = (string) ($rPeriod ?? 'all'); ?>
<section class="sc-statistics"><div class="sc-page-heading"><div><p class="sc-eyebrow">System</p><h1>Statistics</h1></div><div class="sc-page-actions"><a class="sc-button sc-button-secondary" href="stream_rank?period=<?php echo urlencode($streamcreedPeriod); ?>&admin_ui=legacy"><i class="fe-corner-up-left" aria-hidden="true"></i> Open full statistics</a></div></div><div class="sc-toolbar"><label class="sc-filter-field"><span>Period</span><select onchange="location.href='stream_rank?period='+encodeURIComponent(this.value)"><?php foreach (['all' => 'All time', 'day' => 'Today', 'week' => 'This week', 'month' => 'This month'] as $streamcreedKey => $streamcreedLabel): ?><option value="<?php echo $streamcreedKey; ?>"<?php echo $streamcreedKey === $streamcreedPeriod ? ' selected' : ''; ?>><?php echo $streamcreedLabel; ?></option><?php endforeach; ?></select></label></div><div class="sc-data-panel"><div class="sc-table-scroll"><table class="sc-data-table"><thead><tr><th>Rank</th><th>Stream</th><th>Connections</th><th>Users</th><th>Watch time</th></tr></thead><tbody><?php foreach ($streamcreedRows as $streamcreedIndex => $streamcreedRow): ?><tr><td><strong><?php echo $streamcreedIndex + 1; ?></strong></td><td><div class="sc-table-identity"><a href="stream_view?id=<?php echo intval($streamcreedRow['id'] ?? $streamcreedRow['stream_id'] ?? 0); ?>"><?php echo htmlspecialchars((string) ($streamcreedRow['stream_display_name'] ?? 'Unknown stream'), ENT_QUOTES, 'UTF-8'); ?></a></div></td><td><?php echo number_format((float) ($streamcreedRow['connections'] ?? 0)); ?></td><td><?php echo number_format((float) ($streamcreedRow['users'] ?? 0)); ?></td><td><?php echo number_format((float) ($streamcreedRow['time'] ?? 0)); ?></td></tr><?php endforeach; ?><?php if (!$streamcreedRows): ?><tr><td class="sc-table-state" colspan="5">No stream statistics are available for this period.</td></tr><?php endif; ?></tbody></table></div></div></section>
